package com.url_shortener.service; import com.url_shortener.exception.ShortCodeGenerationException; import com.url_shortener.exception.ShortUrlNotFoundException; import com.url_shortener.model.Url; import com.url_shortener.repository.UrlRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Duration; import java.time.Instant; import java.util.Optional; import java.util.Random; import java.util.concurrent.ThreadLocalRandom; import java.util.regex.Matcher; import java.util.regex.Pattern; @Service public class UrlShorteningService { private final UrlRepository urlRepository; @Value("${url.shortener.shortCodeLength:6}") private int shortCodeLength; @Value("${url.shortener.maxGenerationAttempts:10}") private int maxGenerationAttempts; private static final String ALPHANUMERIC_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"; private static final Pattern URL_VALIDATION_PATTERN = Pattern.compile( "^(https?|ftp|file)://[-a-zA-Z0-9+&@#/%?=~_|!:,.;]*[-a-zA-Z0-9+&@#/%=~_|]" ); public UrlShorteningService(UrlRepository urlRepository) { this.urlRepository = urlRepository; } @Transactional public Url createShortUrl(String originalUrl, Duration customExpiration) { if (!isValidUrl(originalUrl)) { throw new IllegalArgumentException("Invalid URL format: " + originalUrl); } Optional<Url> existingUrl = urlRepository.findByOriginalUrl(originalUrl); if (existingUrl.isPresent()) { return existingUrl.get(); } String shortCode = generateUniqueShortCode(); Instant now = Instant.now(); Instant expirationDate = (customExpiration != null) ? now.plus(customExpiration) : null; Url url = new Url(originalUrl, shortCode, now, expirationDate); return urlRepository.save(url); } @Transactional public String getOriginalUrl(String shortCode) { Url url = urlRepository.findByShortCode(shortCode) .orElseThrow(() -> new ShortUrlNotFoundException(shortCode)); if (url.getExpirationDate() != null && url.getExpirationDate().isBefore(Instant.now())) { throw new ShortUrlNotFoundException(shortCode + " (expired)"); } incrementClickCount(url); return url.getOriginalUrl(); } @Transactional protected void incrementClickCount(Url url) { url.setClickCount(url.getClickCount() + 1); urlRepository.save(url); } private String generateUniqueShortCode() { Random random = ThreadLocalRandom.current(); for (int i = 0; i < maxGenerationAttempts; i++) { StringBuilder sb = new StringBuilder(); for (int j = 0; j < shortCodeLength; j++) { sb.append(ALPHANUMERIC_CHARS.charAt(random.nextInt(ALPHANUMERIC_CHARS.length()))); } String shortCode = sb.toString(); if (!urlRepository.existsByShortCode(shortCode)) { return shortCode; } } throw new ShortCodeGenerationException("Failed to generate a unique short code after " + maxGenerationAttempts + " attempts."); } private boolean isValidUrl(String url) { if (url == null || url.trim().isEmpty()) { return false; } Matcher matcher = URL_VALIDATION_PATTERN.matcher(url); return matcher.matches(); } public Optional<Url> findShortUrlByCode(String shortCode) { return urlRepository.findByShortCode(shortCode); } }